def sel_agreement(sel_a, sel_b):
    """Per-element set agreement of selected experts, averaged over heads."""
    fracs = []
    for ea, eb in zip(sel_a, sel_b):
        N = ea.size(0)
        agree = 0
        for n in range(N):
            sa = set(ea[n].tolist()); sb = set(eb[n].tolist())
            agree += len(sa & sb) / max(len(sa | sb), 1)
        fracs.append(agree / N)
    return sum(fracs) / len(fracs)

